import Foundation

protocol FavoritesStore {
    func load() -> [Movie]
    func save(_ movies: [Movie])
}

/// Persists the full `Movie` values as JSON in `UserDefaults`, preserving order.
struct UserDefaultsFavoritesStore: FavoritesStore, @unchecked Sendable {
    private let defaults: UserDefaults
    private let key: String

    init(defaults: UserDefaults = .standard, key: String = "favorites.movies") {
        self.defaults = defaults
        self.key = key
    }

    func load() -> [Movie] {
        guard let data = defaults.data(forKey: key) else { return [] }
        return (try? JSONDecoder().decode([Movie].self, from: data)) ?? []
    }

    func save(_ movies: [Movie]) {
        guard let data = try? JSONEncoder().encode(movies) else { return }
        defaults.set(data, forKey: key)
    }
}
